{
  "title": "The Mirror's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the ruined gate.",
      "visual_description": "Crumbled stone archway with rusted hinges, old royal banners tattered in the wind, and a cracked cobblestone path leading inward.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a cursed tower.",
      "visual_description": "The lamp's flame eye glows intensely as it faces a distant spiral tower wrapped in thorny vines, with a pale blue light pulsing at its peak.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "Mara unfolds a map on a fallen pillar.",
      "visual_description": "Mara spreads an inked parchment across a cracked marble pillar, her compass spinning as she plots a route past the tower.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts a side alley.",
      "visual_description": "The tiny metal fox slinks through rubble, its blue glass eyes scanning for movement, tail ticking with each step.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Glass diver finds a mirror door in a collapsed wall.",
      "visual_description": "A full-length silvered mirror leans against a broken wall, reflecting a warped image of the street behind them.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Mara decides to use the mirror as a passage.",
      "visual_description": "Mara presses her palm against the mirror's surface, watching ripples spread, as the team prepares to enter.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "They emerge inside the cursed tower's base.",
      "visual_description": "A circular chamber with stone floor etched in glowing runes, a spiral staircase ascending into shadow, and a heavy iron door at the far end.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The sleeping tax collector blocks the staircase.",
      "visual_description": "A man in a wrinkled coat slumps on the bottom step, using a massive ledger as a pillow, stamped papers fluttering from his sleeves.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp tries to wake him.",
      "visual_description": "The lamp hovers close, its flame flickering near the collector's face, but he only mutters and turns over.",
      "characters": ["oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Tin fox slips past and finds a key.",
      "visual_description": "The clockwork fox squeezes under the collector's arm, retrieves a brass key from his coat pocket, and returns silently.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Glass diver uses the key on a magic door.",
      "visual_description": "At the top of the stairs, a door of polished obsidian swirls with mist; the key fits perfectly, and the mist parts.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "They enter a treasure room rumored to hold a dragon.",
      "visual_description": "A vast hall with heaps of gold coins and jewels, but no dragon—only a large, empty throne shaped like coiled serpentine scales.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara spots a hidden exit behind a tapestry.",
      "visual_description": "She pulls back a moth-eaten banner depicting a royal crest, revealing a narrow stone passageway.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The corridor leads to a balcony overlooking a bridge.",
      "visual_description": "A crumbling balcony with a view of a long stone bridge spanning a chasm, with torchlight flickering at the far side.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols march across the bridge.",
      "visual_description": "Silhouettes of figures in dark plate armor move in formation, their footsteps echoing on the stone, but no faces visible under visors.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Glass diver swims through a window to distract them.",
      "visual_description": "He dives into a broken window pane and emerges on the bridge's underside, causing a clatter that draws the patrols away.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The team races across the bridge.",
      "visual_description": "Mara runs with the map in hand, the oracle lamp bobs beside her, the tin fox scurries ahead, and glass diver rejoins from a puddle reflection.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the misty ruins beyond.",
      "visual_description": "The bridge ends at a broken archway shrouded in fog, the team disappearing into the white as the city recedes behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ],
  "gate_token": "q_GxQNEp_EAHAIbtt6BUrQ"
}

